'use strict';
// Synthetic incident workbench. No recovery, resend, balance or permission commands.
const incidentStatuses={new:['Новое','New'],investigating:['В работе','Investigating'],waiting:['Ожидает подтверждения','Awaiting evidence'],closed:['Закрыто','Closed']};
const incidentPriorities={high:['Высокая','High'],normal:['Обычная','Normal']};
const incidentFixtures=[
 {id:'INC-101',key:'noor',uid:'U-DEMO-002',sid:'S-DEMO-002',ticket:'T-101',name:'Demo Noor',venue:'Polymarket',date:'2026-10-23',priority:'high',status:'waiting',assignee:'STAFF-203',title:['Неизвестен результат заявки','Order outcome unknown'],impact:['Повторная отправка заявки недоступна до сверки.','Resending the order is unavailable until reconciliation.'],fact:['Заявка ORD-002 отправлена; итог площадкой не подтверждён.','Order ORD-002 was submitted; the venue has not confirmed the outcome.'],missing:['Нужен подтверждённый итог исходной заявки.','The original order needs a confirmed outcome.'],restriction:['Повтор заявки заблокирован; резерв сохраняется.','Resending is blocked; the reserve is retained.'],evidence:null,resolved:false},
 {id:'INC-102',key:'orion',uid:'U-DEMO-009',sid:'S-DEMO-009',ticket:'T-103',name:'Demo Orion',venue:'Limitless',date:'2026-10-22',priority:'high',status:'investigating',assignee:'STAFF-206',title:['Не обновляются данные сессии','Session data is not updating'],impact:['Снимок сессии устарел. Новые действия требуют свежих данных.','The session snapshot is stale. New actions require fresh data.'],fact:['Последний снимок — 10:20 UTC. Подтверждения восстановления пока нет.','Latest snapshot: 10:20 UTC. Recovery has not been confirmed yet.'],missing:['Нужна отдельная проверка восстановления потока.','A separate feed recovery check is required.'],restriction:['Ограничение новых действий проверяется отдельно от закрытия инцидента.','The restriction on new actions is checked separately from incident closure.'],evidence:null,resolved:false},
 {id:'INC-103',key:'robin',uid:'U-DEMO-005',sid:'S-DEMO-005',ticket:'T-102',name:'Demo Robin',venue:'Limitless',date:'2026-10-21',priority:'normal',status:'closed',assignee:'STAFF-203',title:['Задержка уведомления об исполнении','Fill notification delay'],impact:['Проверена задержка уведомления. Частичное исполнение заявки остаётся отдельным фактом.','The notification delay was checked. A partial order fill remains a separate fact.'],fact:['EVID-DEMO-103 подтверждает обработку уведомления.','EVID-DEMO-103 confirms notification processing.'],missing:['Для исходной причины закрытия данных достаточно.','Evidence is sufficient for the original closure reason.'],restriction:['Закрытие не отменяет остаток заявки и не меняет её результат.','Closure does not cancel the order remainder or change its outcome.'],evidence:'EVID-DEMO-103',resolved:true}
];
const incidentAccess=role=>({read:role!=='marketing',write:['ownerA','ownerB','lead','ops'].includes(role)});
function newIncidents(){return{records:structuredClone(incidentFixtures).map(x=>({...x,version:1,note:'',notes:[],events:[],closeReason:x.status==='closed'?'Проверена задержка уведомления.':'',draft:null})),id:'INC-101',q:'',status:'all',priority:'all',venue:'all',assignee:'all',from:'2026-10-17',to:'2026-10-23',sort:'newest',transition:null,error:null,notice:null,returnTicket:false,returnContext:false,scroll:0};}
let incidents=newIncidents();
const il=(dict,k)=>pl(...dict[k]);
const ib=(ru,en,a,extra='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-incident="${a}" ${extra}>${ru===en?escape(ru):pl(ru,en)}</button>`;
const incidentAllowed=x=>Boolean(account?.logged&&incidentAccess(state.role).read&&(!actor().limited||x.uid==='U-DEMO-002'));
const incidentCurrent=()=>incidents.records.find(x=>x.id===incidents.id&&incidentAllowed(x));
const incidentError=(ru,en)=>{incidents.error=[ru,en];return false;};
function incidentRows(){const q=incidents.q.trim().toLowerCase();return incidents.records.filter(x=>incidentAllowed(x)&&(!q||[x.id,x.uid,x.name,...x.title,x.sid,x.ticket].join(' ').toLowerCase().includes(q))&&['status','priority','venue','assignee'].every(k=>incidents[k]==='all'||incidents[k]===x[k])&&x.date>=incidents.from&&x.date<=incidents.to).sort((a,b)=>a.date.localeCompare(b.date)*(incidents.sort==='oldest'?1:-1));}
function incidentEvent(x,ru,en){x.version++;x.events.push({author:accountName()+' · '+actor().id,time:new Date().toISOString(),version:x.version,label:[ru,en]});}
function incidentList(){if(!incidentAccess(state.role).read)return incidentDenied();const rows=incidentRows(), fields=[['status','Статус','Status',Object.entries(incidentStatuses).map(([k,l])=>[k,pl(...l)])],['priority','Важность','Priority',Object.entries(incidentPriorities).map(([k,l])=>[k,pl(...l)])],['venue','Площадка','Venue',[['Polymarket','Polymarket'],['Limitless','Limitless']]],['assignee','Ответственный','Assignee',feedbackAssignees()]];return supportHeading(pl('Инциденты','Incidents'),pl('Разбирайте проблемы по фактам. Закрытие записи не снимает ограничения и не выполняет операции.','Investigate using evidence. Closing a record does not lift restrictions or execute operations.'))+`<section class="panel support-filters"><div class="field"><label for="incident-q">${pl('Поиск по теме, пользователю или ID','Find by topic, user or ID')}</label><input id="incident-q" type="search" value="${escape(incidents.q)}"></div>${fields.map(([k,ru,en,vs])=>feedbackSelect('incident-'+k,pl(ru,en),[['all',pl('Все','All')],...vs],incidents[k])).join('')}${['from','to'].map(k=>`<div class="field"><label for="incident-${k}">${k==='from'?pl('Создано с · UTC','Created from · UTC'):pl('По дату · UTC','Through · UTC')}</label><input id="incident-${k}" type="date" value="${incidents[k]}"></div>`).join('')}${ib('Сбросить фильтры','Reset filters','reset')}${incidents.error?`<p role="alert">${pl(...incidents.error)}</p>`:''}</section><section class="panel"><div class="support-table-top"><h2>${pl('Инциденты','Incidents')} · ${rows.length}</h2>${feedbackSelect('incident-sort',pl('Порядок','Sort'),[['newest',pl('Сначала новые','Newest first')],['oldest',pl('Сначала старые','Oldest first')]],incidents.sort)}</div><div class="table-wrap"><table class="incident-table"><thead><tr>${['Проблема|Issue','Важность|Priority','Статус|Status','Площадка|Venue','Ответственный|Assignee','Создано · UTC|Created · UTC'].map(x=>`<th scope="col">${pl(...x.split('|'))}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${ib(...x.title,'open',`data-id="${x.id}"`)}<small>${x.id} · ${x.name} · ${x.sid}</small></td><td><span class="badge ${x.priority==='high'?'warn':''}">${il(incidentPriorities,x.priority)}</span></td><td>${il(incidentStatuses,x.status)}</td><td>${x.venue}</td><td>${supportWho(x.assignee)}</td><td>${x.date}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':`<div class="empty"><h2>${pl('Инцидентов по этому отбору нет','No matching incidents')}</h2>${ib('Сбросить фильтры','Reset filters','reset')}</div>`}</section><p class="muted">${pl('Три учебных инцидента. Показаны все доступные результаты.','Three synthetic incidents. All permitted results are shown.')}</p>`;}
function incidentDenied(){return supportHeading(pl('Инцидент недоступен','Incident unavailable'),pl('Проверьте назначение и область доступа.','Check your assignment and access scope.'));}
function incidentDetail(){const x=incidentCurrent();if(!x)return incidentDenied();const w=incidentAccess(state.role).write,d=x.draft||x;return ib('К инцидентам','Back to incidents','back')+supportHeading(pl(...x.title),`${x.id} · ${x.venue} · ${pl('Демо','Demo')} · ${x.date} UTC`)+`${incidents.notice?`<p role="status" class="support-notice">${pl(...incidents.notice)}</p>`:''}${!w?`<p class="support-notice">${pl('Только просмотр. Изменения и внутренние заметки недоступны.','Read only. Changes and internal notes are unavailable.')}</p>`:''}<div class="support-layout"><div><section class="panel"><h2>${pl('Что произошло','What happened')}</h2><p class="incident-impact">${pl(...x.impact)}</p><dl class="feedback-meta"><dt>${pl('Факты при обнаружении','Facts at detection')}</dt><dd>${pl(...x.fact)}</dd><dt>${pl('Чего не хватает','Missing evidence')}</dt><dd>${x.resolved?pl('Причина подтверждена как устранённая.','The cause is confirmed resolved.'):pl(...x.missing)}</dd><dt>${pl('Подтверждение','Evidence')}</dt><dd>${x.evidence||pl('Не получено','Not received')}</dd></dl></section><section class="panel"><h2>${pl('Работа с инцидентом','Incident handling')}</h2><p><span class="badge">${il(incidentStatuses,x.status)}</span> · ${il(incidentPriorities,x.priority)}</p>${x.status==='closed'?`<p>${pl('Причина закрытия','Closure reason')}: ${escape(x.closeReason)}</p>`:`<form id="incident-form">${feedbackSelect('incident-edit-status',pl('Рабочий статус','Working status'),Object.entries(incidentStatuses).filter(([k])=>k!=='closed').map(([k,l])=>[k,pl(...l)]),d.status,!w)}${feedbackSelect('incident-edit-assignee',pl('Ответственный','Assignee'),feedbackAssignees(),d.assignee,!w)}${w?`<button class="btn primary" type="submit">${pl('Сохранить изменения','Save changes')}</button> ${ib('Отменить изменения','Discard changes','discard')}`:''}</form>`}${incidents.error?`<p class="account-error" role="alert">${pl(...incidents.error)}</p>`:''}${w?`<div class="incident-actions">${x.status==='closed'?ib('Возобновить разбор','Reopen investigation','prepare-reopen'):ib('Проверить закрытие','Review closure','prepare-close')}</div>`:''}<p class="muted">${pl('Статус обращения поддержки меняется отдельно. Сообщение пользователю не отправляется.','Support status changes separately. No message is sent to the user.')}</p></section>${w?`<section class="panel"><h2>${pl('Внутренние заметки','Internal notes')}</h2>${x.notes.map(n=>`<article class="support-message internal"><strong>${escape(n.author)}</strong><p>${escape(n.body)}</p></article>`).join('')}<label for="incident-note">${pl('Только сотрудникам — пользователь не увидит','Staff only — hidden from the user')}</label><textarea id="incident-note" rows="3" maxlength="2000">${escape(x.note)}</textarea>${ib('Добавить заметку','Add note','note')}</section>`:''}<details class="panel"><summary>${pl('История инцидента','Incident history')} · ${x.events.length}</summary>${x.events.map(e=>`<p>${escape(e.author)} · ${e.time} · v${e.version}<br>${escape(pl(...e.label))}</p>`).join('')||`<p>${pl('Новых изменений в этом учебном сеансе нет.','No new changes in this synthetic session.')}</p>`}</details></div><aside class="support-context"><section class="panel"><h2>${pl('Что остаётся ограничено','Restrictions remain')}</h2><p>${pl(...x.restriction)}</p><p class="muted">${pl('Закрытие не возобновляет торговлю, не освобождает резерв и не отменяет технический режим.','Closure does not resume trading, release reserves or cancel maintenance mode.')}</p></section><section class="panel"><h2>${pl('Связанные записи','Related records')}</h2><p>${x.name}<br>${x.uid}<br>${x.sid}</p>${ib('Открыть пользователя','Open user','user')}${ib('Открыть сессию','Open session','session')}${ib('Обращение '+x.ticket,'Conversation '+x.ticket,'ticket')}${reconciliationIncidentLinks()}<p class="muted">${pl('Связаны тот же пользователь, площадка и сессия.','The same user, venue and session are linked.')}</p></section>${w?`<details class="panel"><summary>${pl('Учебные состояния проверки','Test evidence states')}</summary><p>${pl('Это подготовленные данные прототипа, а не запрос на площадку.','Prepared prototype evidence, not a request to the venue.')}</p>${x.key==='orion'?ib('Показать подтверждение восстановления','Load recovery evidence example','evidence'):''}${ib('Имитировать новую версию','Simulate a newer version','conflict')}</details>`:''}</aside></div>${incidents.transition?incidentTransition(x):''}`;}
function incidentTransition(x){const d=incidents.transition,reopen=d.kind==='reopen';return `<dialog class="incident-dialog" aria-labelledby="incident-dialog-title"><h2 id="incident-dialog-title">${reopen?pl('Возобновить разбор','Reopen investigation'):pl('Проверка закрытия','Closure review')}</h2><p>${x.id} · ${x.name} · ${x.venue}</p><p>${reopen?pl('Прежняя причина и подтверждения останутся в истории.','Previous reasons and evidence stay in history.'):x.resolved?pl('Есть подтверждение устранения причины: ','Resolution evidence: ')+x.evidence:pl('Закрытие недоступно: причина ещё не устранена или не подтверждена.','Closure unavailable: the cause is unresolved or unconfirmed.')}</p><div class="field"><label for="incident-reason">${pl('Причина','Reason')}</label><textarea id="incident-reason" rows="3" maxlength="1000">${escape(d.reason)}</textarea></div><label class="incident-confirm"><input id="incident-ack" type="checkbox" ${d.ack?'checked':''}>${pl('Понимаю: это не снимает ограничения и не меняет торговые операции.','I understand: this does not lift restrictions or change trade operations.')}</label>${d.error?`<p role="alert" class="account-error">${pl(...d.error)}</p>`:''}<div class="incident-actions">${ib('Отмена','Cancel','cancel-transition')}${ib(reopen?'Возобновить':'Закрыть инцидент',reopen?'Reopen':'Close incident','confirm-transition',(!reopen&&!x.resolved)?'disabled':'',true)}</div></dialog>`;}
function incidentSave(){const x=incidentCurrent();if(!x||!incidentAccess(state.role).write||x.status==='closed')return false;const d=x.draft;if(!d)return true;if(d.version!==x.version)return incidentError('Запись изменилась. Отмените устаревшие изменения и проверьте текущие значения.','The record changed. Discard outdated changes and review current values.');if(!['new','investigating','waiting'].includes(d.status)||!feedbackAssignees().some(a=>a[0]===d.assignee))return false;const old=x.status,assignee=x.assignee;x.status=d.status;x.assignee=d.assignee;incidentEvent(x,`Статус: ${incidentStatuses[old][0]} → ${incidentStatuses[x.status][0]}; ответственный: ${assignee} → ${x.assignee}`,`Status: ${old} → ${x.status}; assignee: ${assignee} → ${x.assignee}`);x.draft=null;incidents.notice=['Изменения сохранены. Обращение и операции не изменены.','Changes saved. Conversation and operations are unchanged.'];return true;}
function incidentAction(a,el={dataset:{}}){const hadTransition=!!incidents.transition;incidents.error=null;incidents.notice=null;if(a==='open'&&el.dataset.id){const target=incidents.records.find(x=>x.id===el.dataset.id&&incidentAllowed(x));if(!target)return;incidents.id=target.id;incidents.returnTicket=false;incidents.scroll=window.scrollY;navigate('incident');return;}if(a==='list'||a==='back'){incidents.transition=null;navigate('incidents');window.scrollTo(0,incidents.scroll);return;}if(a==='reset'){Object.assign(incidents,{q:'',status:'all',priority:'all',venue:'all',assignee:'all',from:'2026-10-17',to:'2026-10-23'});render();return;}const x=incidentCurrent();if(!x)return;if(a==='return'){incidents.returnContext=false;incidents.returnTicket=false;navigate('incident');return;}if(a==='ticket'){const q=support.records.find(t=>t.id===x.ticket&&supportAllowed(t)&&t.uid===x.uid&&t.sid===x.sid&&t.venue===x.venue);if(!q)return;supportActivate(q.id);support.linked=false;feedback.returnFromTicket=false;incidents.returnTicket=true;navigate('ticket');return;}if(['user','session'].includes(a)){incidents.returnContext=true;support.linked=false;feedback.linkedContext=false;state.userId=x.uid;state.sessionId=x.sid;state.tab='overview';navigate(a);return;}if(!incidentAccess(state.role).write)return;if(a==='discard')x.draft=null;if(a==='note'){if(!x.note.trim())incidentError('Введите текст заметки.','Enter a note.');else{x.notes.push({body:x.note.trim(),author:accountName()+' · '+actor().id});x.note='';incidentEvent(x,'Добавлена внутренняя заметка','Internal note added');if(x.draft?.version===x.version-1)x.draft.version=x.version;}}if(a==='evidence'&&x.key==='orion'&&!x.resolved){x.evidence='EVID-DEMO-102';x.resolved=true;incidentEvent(x,'Получен учебный результат проверки потока EVID-DEMO-102','Received synthetic feed check EVID-DEMO-102');if(x.draft?.version===x.version-1)x.draft.version=x.version;incidents.notice=['Учебное подтверждение получено. Инцидент не закрыт; снимок сессии и ограничения прежние.','Sample evidence received. The incident is not closed; session snapshot and restrictions are unchanged.'];}if(a==='conflict'){x.draft??={status:x.status,assignee:x.assignee,version:x.version};x.version++;incidents.notice=['Получена новая учебная версия. Устаревшее подтверждение будет отклонено.','A newer sample version is available. Outdated confirmation will be rejected.'];}if(a==='prepare-close'||a==='prepare-reopen'){if(x.draft&&(x.draft.status!==x.status||x.draft.assignee!==x.assignee)){incidentError('Сначала сохраните или отмените изменения обработки.','Save or discard handling changes first.');render();return;}incidents.transition={kind:a==='prepare-reopen'?'reopen':'close',version:x.version,reason:'',ack:false,error:null};}if(a==='cancel-transition')incidents.transition=null;if(a==='confirm-transition'&&incidents.transition){const d=incidents.transition;const fail=(ru,en)=>d.error=[ru,en];if(d.version!==x.version)fail('Запись изменилась. Закройте проверку и откройте её заново.','The record changed. Cancel and reopen this review.');else if(d.reason.trim().length<5||!d.ack)fail('Укажите причину и подтвердите последствия.','Enter a reason and acknowledge the consequences.');else if(d.kind==='close'&&(!x.resolved||!x.evidence||x.status==='closed'))fail('Нет подтверждения устранения причины.','The cause has no resolution evidence.');else if(d.kind==='reopen'&&x.status!=='closed')fail('Инцидент уже открыт.','The incident is already open.');else{const reopen=d.kind==='reopen',previous=x.evidence,previousReason=x.closeReason;x.status=reopen?'investigating':'closed';if(reopen){x.resolved=false;x.evidence=null;}else x.closeReason=d.reason.trim();incidentEvent(x,(reopen?'Разбор возобновлён: ':'Закрыто: ')+d.reason.trim()+(reopen?' · Прежнее подтверждение: '+(previous||'—')+' · Прежняя причина: '+previousReason:''),(reopen?'Investigation reopened: ':'Closed: ')+d.reason.trim()+(reopen?' · Previous evidence: '+(previous||'—')+' · Previous reason: '+previousReason:''));x.draft=null;incidents.transition=null;incidents.notice=['Состояние инцидента изменено. Ограничения, обращение и торговые операции прежние.','Incident state changed. Restrictions, conversation and trade operations are unchanged.'];}}render();if(incidents.transition)document.querySelector('#incident-reason')?.focus();else if(hadTransition)document.querySelector('[data-incident="'+(x.status==='closed'?'prepare-reopen':'prepare-close')+'"]')?.focus();}
function incidentTicketLinks(){if(incidents.returnTicket)return ib('Вернуться к инциденту','Back to incident','return');return incidents.records.filter(x=>incidentAllowed(x)&&x.ticket===support.id).map(x=>ib('Инцидент '+x.id,'Incident '+x.id,'open',`data-id="${x.id}"`)).join('');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-incident]');if(b&&!b.disabled)incidentAction(b.dataset.incident,b);});
document.addEventListener('input',e=>{const id=e.target.id,x=incidentCurrent();if(id==='incident-note'&&x&&incidentAccess(state.role).write)x.note=e.target.value;if(id==='incident-reason'&&incidents.transition)incidents.transition.reason=e.target.value;if(id==='incident-q'){incidents.q=e.target.value;const p=e.target.selectionStart;render();const n=document.querySelector('#incident-q');n.focus();if(p!==null)n.setSelectionRange(p,p);}});
document.addEventListener('change',e=>{const id=e.target.id,v=e.target.value,x=incidentCurrent();if(id==='incident-ack'&&incidents.transition)incidents.transition.ack=e.target.checked;else if(id.startsWith('incident-edit-')&&x&&incidentAccess(state.role).write){x.draft??={status:x.status,assignee:x.assignee,version:x.version};x.draft[id.slice(14)]=v;}else if(id.startsWith('incident-')){const k=id.slice(9);if(['status','priority','venue','assignee','from','to','sort'].includes(k)){if(['from','to'].includes(k)&&(!v||(k==='from'?v>incidents.to:v<incidents.from))){incidentError('Проверьте порядок дат.','Check the date order.');render();return;}incidents[k]=v;incidents.error=null;render();}}});
document.addEventListener('submit',e=>{if(e.target.id==='incident-form'){e.preventDefault();incidentSave();render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&incidents.transition){e.preventDefault();incidentAction('cancel-transition');}});

function incidentDialog(){const d=document.querySelector('.incident-dialog');if(d&&!d.open){d.showModal();document.querySelector('#incident-reason')?.focus();}}

function incidentReturnAvailable(){const x=incidentCurrent();return incidents.returnContext&&!!x&&state.userId===x.uid&&(!['session','order'].includes(state.route)||state.sessionId===x.sid);}
